def evaluate(expr,typ):
 def w(n):
  if isinstance(n,ast.Constant) and type(n.value) is int:return typ(n.value)
  if isinstance(n,ast.BinOp):
   a,b=w(n.left),w(n.right)
   if isinstance(n.op,ast.Add):return a+b
   if isinstance(n.op,ast.Sub):return a-b
   if isinstance(n.op,ast.Mult):return a*b
   if isinstance(n.op,ast.Div):return a/b
  raise ValueError(expr)
 return w(ast.parse(expr,mode='eval').body)
def paths(edges,start='S',end='T'):
 out=[]
 def visit(u,p):
  if u==end:out.append(p);return
  for a,b in edges:
   if a==u and b not in p:visit(b,p+[b])
 visit(start,[start]);return out
def oracle(m):
 k=m['kind']
 if k=='layers':
  objects={(r,c) for r,n in enumerate(m['row_lengths']) for c in range(n)};assert len(objects)==m['expected'];return dict(objects=sorted(objects),count=len(objects))
 if k=='alternating':
  rows=[dict(count=m['start']-i,type=m['types'][i%2]) for i in range(m['rows'])];assert [r['count'] for r in rows]==m['expected_counts'] and rows[-1]['type']==m['expected_type'];assert sum(r['count'] for r in rows)==m['expected'];return dict(rows=rows)
 if k=='animals':
  trials=[[g,m['total']-g,2*g+4*(m['total']-g)] for g in range(1,m['total'])];sol=[[g,r] for g,r,l in trials if l==m['legs']];assert sol==m['expected'];return dict(trials=trials,solutions=sol)
 if k=='distribution':
  allocations=[list(p) for p in product(range(1,m['total']),repeat=m['people']) if sum(p)==m['total']];hits=[p for p in allocations if p[m['event_index']]==m['event_value']];assert hits and len(hits)<len(allocations);return dict(allocations=allocations,event_count=len(hits),classification='possible_not_certain')
 if k=='distribution_bounds':
  pairs=[[a,b] for a in range(1,m['total']) for b in range(1,m['total']) if a+b==m['total']];assert pairs==m['expected_pairs'];assert all(a<7 for a,b in pairs) and not any(b==7 for a,b in pairs);return dict(pairs=pairs,P='certain',Q='impossible')
 if k=='sequence_graph':
  pp=paths(m['edges']);valid=[p for p in pp if [m['values'][x] for x in p[1:-1]]==m['target']];assert valid==m['expected'];return dict(all_routes=pp,valid=valid)
