  # Exact remainder samples exercise lower endpoint inclusion and excluded upper endpoint.
  unit=Fraction(m['unit']);base=Fraction(m['full'])*unit;assert base==m['lower'] and base+unit==m['upper'];samples=[Fraction(0),Fraction(1,2),unit-Fraction(1,2),unit];valid=[r for r in samples if (0<r<unit if m['strict'] else 0<=r<unit)];assert unit not in valid and ((Fraction(0) in valid)==(not m['strict']));return dict(base=str(base),upper=str(base+unit),valid_test_remainders=[str(r) for r in valid],reason='For every permitted r, L=base+r; endpoint membership follows exact supplied inequality, samples are boundary regression only.')
