 if k=='scaled':
  distances={n:len(range(min(p,m['positions'][m['origin']]),max(p,m['positions'][m['origin']]))) * m['scale'] for n,p in m['positions'].items() if n!=m['origin']};selected=[n for n,d in distances.items() if (d<=m['threshold'] if m['inclusive'] else d<m['threshold'])];assert selected==m['expected'];return dict(distances=distances,selected=selected)
