  trials=[list(p) for p in permutations(m['cards']) if p[0]+2==6 and p[1]-p[0]==4 and p[2]+p[1]==14 and p[3]+p[2]==10];assert trials==m['expected'];return dict(permutations_checked=24,solutions=trials,forced_values=[4,8,6,4],inventory_violation='4 required twice; only one card 4')
